insert into public.project_templates (name, description, category, default_priority, objective) values ('Corrigir planilha com nomes de produtos e disponibilizar para todos', 'Corrige e padroniza a planilha de nomes/códigos de produtos e deixa disponível pra todo o time.', 'Administrativo/Dados', 'medium', 'Ter uma planilha de produtos consistente com o cadastro oficial, publicada e com responsável definido pela manutenção.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Compra de materiais de escritório', 'Levanta necessidades, cota e formaliza a compra de materiais de escritório.', 'Administrativo/Compras', 'medium', 'Repor materiais de escritório com cotação comparada e aprovação formal antes da compra.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Cores dos produtos China', 'Define e homologa a cor oficial de produtos fabricados na China, do briefing à aprovação final.', 'Sourcing China', 'medium', 'Ter a cor de cada produto aprovada e homologada contra a paleta oficial da marca antes da produção em escala.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Feira Reval — Organização, espaço', 'Planeja e executa a presença da Cardoso numa feira, do briefing ao relatório pós-evento.', 'Evento/Feira', 'medium', 'Ter o estande aprovado, montado e presente na feira, com relatório de resultados ao final.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Feira Ri Happy', 'Organiza a presença da Cardoso numa feira de key account, alinhada com o comercial (lógica JBP).', 'Evento/Feira (Key Account)', 'medium', 'Executar a feira do key account com verba e material aprovados, e relatório comercial ao final.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Uniformes promotores', 'Desenvolve e produz uniformes para promotores, do briefing à distribuição.', 'Produção Têxtil', 'medium', 'Ter o uniforme de promotores aprovado (com prova física validada) e distribuído.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Show room', 'Reforma ou monta um showroom físico, do levantamento de necessidades à entrega da obra.', 'Obra/Reforma física', 'medium', 'Entregar o showroom reformado, com projeto técnico e orçamento aprovados antes da execução.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Novos painéis da Fábrica', 'Cria e instala novos painéis de sinalização na fábrica, com teste de material antes da produção.', 'Sinalização/Material físico', 'medium', 'Ter os painéis com material testado e aprovado, produzidos e instalados.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Avisos com novos layouts', 'Atualiza avisos internos pra um layout novo e padronizado, com teste de material antes da produção.', 'Sinalização/Material físico', 'medium', 'Ter todos os avisos padronizados no novo layout, com material testado e inventário atualizado.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Display Fofush', 'Concebe e produz um display de PDV para a linha Fofush, do briefing à distribuição em loja.', 'Material PDV', 'medium', 'Ter o display de PDV aprovado, produzido e distribuído pros lojistas.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Embalagens e adesivos China', 'Desenvolve e homologa embalagens/adesivos de produtos fabricados na China antes da produção em massa.', 'Sourcing China', 'medium', 'Ter a embalagem/adesivo homologado contra o manual de marca antes de confirmar a produção em escala.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Área comercial Site — Reunião só sobre site', 'Coleta e prioriza demandas da área comercial para o site, do alinhamento à publicação.', 'Digital/Site', 'medium', 'Ter o escopo técnico definido com o comercial, testado e publicado no site.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Manual de marca e arquivos de fácil acesso (Cardoso/Tópi/Playmi)', 'Estrutura o manual de marca das 3 marcas e organiza os arquivos oficiais de fácil acesso.', 'Governança de marca', 'medium', 'Ter o manual de marca das 3 marcas publicado, com arquivos organizados e manutenção contínua definida.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Uniformes Fábrica', 'Desenvolve e produz uniformes para o time da fábrica, do levantamento à distribuição.', 'Produção Têxtil', 'medium', 'Ter o uniforme da fábrica aprovado (com prova física validada), produzido e distribuído.');
insert into public.project_templates (name, description, category, default_priority, objective) values ('Alimentar conteúdo no site', 'Levanta, produz e publica conteúdo pendente ou desatualizado no site institucional.', 'Digital/Conteúdo', 'medium', 'Ter o conteúdo do site atualizado, revisado e publicado, com checagem pós-publicação.');
